        h.ui.call(()->{h.space.navigationChangedNative(tab);return null;});h.port.afterTool("browser_task_observe",obj("tabId",tab),next,h.control);assertThrows(BrowserTaskSpace.StalePage.class,()->h.ui.call(()->h.space.sourceFor(current)));assertEquals(2,h.driver.observationReads.get());assertEquals(0,h.sources.writes.get());
