    @Test public void researchJourneyRetainsSourcesDownloadsAndOnlyClosesTaskOwnedPages()throws Exception {try(Harness h=new Harness(true)){
        String[] pages={h.open("one"),h.open("two"),h.open("three")};JSONObject first=null;
        for(String tab:pages){JSONObject observation=h.observe(tab);if(first==null)first=observation;JSONObject saved=h.invoke("retain_source",obj("tabId",tab,"observationId",observation.getString("observationId"),"excerpt","中文"));assertTrue(saved.getBoolean("sourceRetained"));assertFalse(saved.getBoolean("verified"));}
        assertEquals(3,h.sources.writes.get());assertTrue(h.sources.lastSource.getBoolean("untrustedPageContent"));JSONObject read=h.observe(pages[0]);JSONObject download=h.invoke("download",obj("tabId",pages[0],"observationId",read.getString("observationId"),"url","https://example.com/file"));assertEquals("queued",download.getString("status"));assertEquals(1,h.driver.downloads.get());
        h.ui.call(()->{h.space.takeOverNative(pages[1]);return null;});JSONObject ended=h.port.endForOwner("owner_finished");assertEquals(2,ended.getJSONArray("closedTaskTabs").length());assertTrue(h.driver.pages.containsKey(h.driver.ownerId));assertTrue(h.driver.pages.containsKey(pages[1]));assertEquals(2,h.driver.pages.size());assertEquals(3,h.sources.records.size());
    }}
