    @Test public void ownerHandoffHasADefiniteReceiptAndReturnsToFreshObservationInTheOriginalPort()throws Exception {try(Harness h=new Harness(true)){
        String tab=h.open("login");JSONObject before=h.observe(tab);JSONObject handoff=h.invoke("request_user",obj("tabId",tab,"reason","请登录后交还当前页"));assertEquals(handoff.toString(),"owner_control",handoff.getString("status"));assertTrue(handoff.getBoolean("ok"));assertTrue(h.control.isPaused());assertFalse(handoff.optBoolean("requiresPause"));assertFalse(handoff.has("code"));h.port.requireOwnerReturnReady();
        h.ui.call(()->{h.driver.pages.get(tab).put("url","https://example.com/account?view=mine").put("navigation",2L);JSONObject pin=h.space.returnPinNative(tab);h.space.returnOwnerNative(pin,()->{});h.control.resumeAtPauseRevision(pin.getLong("pauseRevision"));return null;});JSONObject old=h.invoke("click",obj("tabId",tab,"observationId",before.getString("observationId"),"ref","n0"));assertFalse(old.getBoolean("accepted"));assertEquals("stale_browser_observation",old.getString("code"));assertFalse(old.getBoolean("requiresPause"));JSONObject fresh=h.observe(tab);assertEquals("observed",fresh.getString("status"));assertEquals(handoff.getString("browserSpaceId"),fresh.getString("browserSpaceId"));assertEquals(h.binding.runId,fresh.getString("runId"));assertNotEquals(before.getLong("tabGeneration"),fresh.getLong("tabGeneration"));
    }}
