    @Test public void originalRunnerFinalOwnerReturnContextAllowsRetentionWithoutAnotherObservation()throws Exception {try(Harness h=new Harness(true)){
        String tab=h.open("owner-return-runner");java.util.concurrent.atomic.AtomicReference<Throwable> failure=new java.util.concurrent.atomic.AtomicReference<>();AtomicInteger rounds=new AtomicInteger();
        dev.pocketengine.core.RunJournal journal=new dev.pocketengine.core.RunJournal(){JSONArray messages=new JSONArray();int steps;public synchronized JSONObject restore()throws Exception{return obj("messages",new JSONArray(messages.toString()),"steps",steps);}public synchronized void checkpoint(JSONArray rows,int count,JSONObject observation)throws Exception{messages=new JSONArray(rows.toString());steps=count;}public String beginOperation(String name,JSONObject args)throws Exception{String id=UUID.randomUUID().toString();h.authority.prepared.put(id,obj("tool",name,"args",new JSONObject(args.toString())));return id;}public void finishOperation(String id,JSONObject receipt){}};
        dev.pocketengine.testutil.HttpServer server=dev.pocketengine.testutil.HttpServer.create(new java.net.InetSocketAddress("127.0.0.1",0),0);
        server.createContext("/",exchange->{try{
            JSONObject request=new JSONObject(new String(exchange.getRequestBody().readAllBytes(),java.nio.charset.StandardCharsets.UTF_8)),answer;int round=rounds.getAndIncrement();
            if(round==0)answer=runnerTool("browser_task_request_user",obj("tabId",tab,"reason","在原页登录后交还"));
            else if(round==1){JSONObject returned=null;JSONArray messages=request.getJSONArray("messages");for(int i=messages.length()-1;i>=0;i--){JSONArray parts=messages.getJSONObject(i).optJSONArray("content");for(int j=0;parts!=null&&j<parts.length();j++){String text=parts.getJSONObject(j).optString("text"),prefix=dev.pocketengine.features.memory.TaskMemoryHistory.OBSERVATION_PREFIX;if(!text.startsWith(prefix))continue;JSONObject value=new JSONObject(text.substring(prefix.length()));if(value.optString("kind").equals("browser_owner_return_observation"))returned=value;}}assertNotNull(returned);assertEquals(1,h.driver.observationReads.get());JSONObject source=obj("tabId",tab,"observationId",returned.getString("observationId"),"excerpt","中文");assertThrows(BrowserTaskSpace.StalePage.class,()->h.ui.call(()->h.space.sourceFor(source)));answer=runnerTool("browser_task_retain_source",source);}
            else{JSONArray messages=request.getJSONArray("messages");JSONObject saved=null;for(int i=messages.length()-1;i>=0;i--)if(messages.getJSONObject(i).optString("role").equals("tool")){saved=new JSONObject(messages.getJSONObject(i).getString("content"));break;}assertNotNull(saved);assertTrue(saved.toString(),saved.optBoolean("sourceRetained"));answer=obj("role","assistant","content","已保留交还后的真实来源。网页业务结果未核实。");}
            byte[] bytes=obj("choices",new JSONArray().put(obj("message",answer,"finish_reason",answer.has("tool_calls")?"tool_calls":"stop"))).toString().getBytes(java.nio.charset.StandardCharsets.UTF_8);exchange.sendResponseHeaders(200,bytes.length);exchange.getResponseBody().write(bytes);
        }catch(Throwable error){failure.compareAndSet(null,error);try{exchange.sendResponseHeaders(500,-1);}catch(Exception ignored){}}finally{exchange.close();}});server.start();ExecutorService runner=Executors.newSingleThreadExecutor();
        try{
            var future=runner.submit(()->new dev.pocketengine.runtime.AgentRunner(null,h.port).run(h.binding.taskId,"在原网页登录后继续读取资料并保留真实来源",new dev.pocketengine.core.ModelConfig("http://127.0.0.1:"+server.getAddress().getPort(),"fixture-local-only","owner-return-source",false,30,6),h.control,event->{},journal));
            long until=System.nanoTime()+5_000_000_000L;while(!h.control.isPaused()&&!future.isDone()&&System.nanoTime()<until)Thread.sleep(5);assertTrue("Runner must reach original owner handoff",h.control.isPaused());while(true){try{h.port.requireOwnerReturnReady();break;}catch(SecurityException settling){if(System.nanoTime()>until)throw settling;Thread.sleep(5);}}
            JSONObject pin=h.ui.call(()->h.space.returnPinNative(tab));h.port.expectOwnerReturnObservation(pin,()->h.authority.check("browser_task_observe",h.control));h.ui.call(()->{h.space.returnOwnerNative(pin,()->{});h.control.resumeAtPauseRevision(pin.getLong("pauseRevision"));return null;});
            var outcome=future.get(12,TimeUnit.SECONDS);if(failure.get()!=null)throw new AssertionError("loopback model fixture",failure.get());assertTrue(outcome.summary,outcome.status.matches("completed|needs_confirmation"));assertEquals(3,rounds.get());assertEquals(1,h.sources.writes.get());assertEquals("中文",h.sources.lastSource.getString("excerpt"));assertEquals(1,h.driver.observationReads.get());
        }finally{runner.shutdownNow();runner.awaitTermination(2,TimeUnit.SECONDS);server.stop(0);}
    }}
    private static JSONObject runnerTool(String name,JSONObject args)throws Exception {return obj("role","assistant","content",JSONObject.NULL,"tool_calls",new JSONArray().put(obj("id",UUID.randomUUID().toString(),"type","function","function",obj("name",name,"arguments",args.toString()))));}
