    @Test public void authorizedPageReadFailureReturnsExactPageToOwnerAndNeedsANewReturnNonce()throws Exception {try(Harness h=new Harness(true)){
        String tab=h.open("login");h.invoke("request_user",obj("tabId",tab,"reason","人工登录"));JSONObject firstPin=h.ui.call(()->h.space.returnPinNative(tab));String first=h.port.expectOwnerReturnObservation(firstPin,()->h.authority.check("browser_task_observe",h.control));h.ui.call(()->{h.space.returnOwnerNative(firstPin,()->{});h.control.resumeAtPauseRevision(firstPin.getLong("pauseRevision"));return null;});h.driver.failObservation=true;JSONObject failed=h.port.contextSnapshot(BrowserTaskCapabilityPort.OWNER_RETURN_CONTEXT).getJSONObject("browserReturnObservation");assertTrue(failed.getBoolean("requiresOwnerReturn"));assertFalse(failed.getBoolean("freshObservationAvailable"));assertTrue(h.control.isPaused());assertFalse(h.driver.owned.containsKey(tab));assertTrue(h.driver.pages.containsKey(tab));h.port.requireOwnerReturnReady();h.driver.failObservation=false;
        JSONObject secondPin=h.ui.call(()->h.space.returnPinNative(tab));String second=h.port.expectOwnerReturnObservation(secondPin,()->h.authority.check("browser_task_observe",h.control));assertNotEquals(first,second);h.ui.call(()->{h.space.returnOwnerNative(secondPin,()->{});h.control.resumeAtPauseRevision(secondPin.getLong("pauseRevision"));return null;});JSONObject observed=h.port.contextSnapshot(BrowserTaskCapabilityPort.OWNER_RETURN_CONTEXT).getJSONObject("browserReturnObservation");assertEquals("observed",observed.getString("status"));assertEquals(second,observed.getString("ownerReturnNonce"));assertEquals(h.space.spaceId,observed.getString("browserSpaceId"));
    }}
